ALTER TABLE public.offices ADD COLUMN office_name text GENERATED ALWAYS AS (name) STORED, ADD COLUMN office_type varchar(100), ADD COLUMN parent_office uuid REFERENCES public.offices(id), ADD COLUMN description text;
ALTER TABLE public.sections ADD COLUMN section_name text GENERATED ALWAYS AS (name) STORED, ADD COLUMN office_id uuid REFERENCES public.offices(id), ADD COLUMN section_head uuid REFERENCES public.officers(id), ADD COLUMN created_at timestamptz DEFAULT now();
ALTER TABLE public.officers ADD COLUMN first_name varchar(150), ADD COLUMN middle_name varchar(150), ADD COLUMN last_name varchar(150), ADD COLUMN next_of_kin_phone varchar(100), ADD COLUMN blood_group varchar(20), ADD COLUMN profile_photo text GENERATED ALWAYS AS (photo_url) STORED, ADD COLUMN designation text GENERATED ALWAYS AS (position) STORED;
ALTER TABLE public.inventory_items ADD COLUMN item_code text GENERATED ALWAYS AS (code) STORED, ADD COLUMN item_name text GENERATED ALWAYS AS (name) STORED, ADD COLUMN quantity_in_stock integer GENERATED ALWAYS AS (quantity) STORED, ADD COLUMN storage_location text GENERATED ALWAYS AS (location) STORED;
ALTER TABLE public.leave_requests ADD COLUMN total_days integer GENERATED ALWAYS AS (end_date - start_date + 1) STORED, ADD COLUMN approval_status text GENERATED ALWAYS AS (status) STORED, ADD COLUMN current_step text GENERATED ALWAYS AS (CASE WHEN status <> 'Pending' THEN status WHEN stage=1 THEN 'Section Head' WHEN stage=2 THEN 'Assistant Commissioner' WHEN stage=3 THEN 'Deputy Commissioner' WHEN stage=4 THEN 'Commandant' ELSE 'Closed' END) STORED;
ALTER TABLE public.notifications ADD COLUMN message text GENERATED ALWAYS AS (body) STORED, ADD COLUMN is_read boolean GENERATED ALWAYS AS (read) STORED;
ALTER TABLE public.audit_logs ADD COLUMN ip_address varchar(100);
CREATE TABLE public.officer_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), officer_id uuid REFERENCES public.officers(id), document_name varchar(255), document_type varchar(100), file_url text, upload_date timestamptz DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.officer_documents TO authenticated; GRANT ALL ON public.officer_documents TO service_role;
ALTER TABLE public.officer_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin manages officer documents" ON public.officer_documents FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_officer_documents AFTER INSERT OR UPDATE OR DELETE ON public.officer_documents FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
