CREATE VIEW public.equipment_requests WITH (security_invoker=true) AS SELECT r.id,r.request_number,r.section_id AS requesting_section,o.id AS requested_by,r.request_date,r.item_name,r.quantity,r.justification AS purpose,r.priority,r.approval_status AS status,r.approval_status AS commandant_approval,r.collection_status,r.created_at FROM public.supply_requests r LEFT JOIN public.officers o ON o.user_id=r.requested_by;
GRANT SELECT ON public.equipment_requests TO authenticated,service_role;
COMMENT ON VIEW public.equipment_requests IS 'Read-only compatibility projection; submit requests through supply_requests and advance only through act_on_supply.';
CREATE VIEW public.approvals WITH (security_invoker=true) AS SELECT r.id::text || ':' || h.ordinality::text AS id,r.id AS request_id,o.id AS approver_id,o.office_id,h.entry->>'action' AS action_taken,h.entry->>'note' AS comments,h.entry->>'at' AS action_date FROM public.supply_requests r CROSS JOIN LATERAL jsonb_array_elements(r.history) WITH ORDINALITY AS h(entry,ordinality) LEFT JOIN public.officers o ON o.email=h.entry->>'by';
GRANT SELECT ON public.approvals TO authenticated,service_role;
COMMENT ON VIEW public.approvals IS 'Read-only approval history; changes originate exclusively from act_on_supply.';
CREATE TRIGGER audit_offices AFTER INSERT OR UPDATE OR DELETE ON public.offices FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TRIGGER audit_sections AFTER INSERT OR UPDATE OR DELETE ON public.sections FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();